public class DbChoiceDemo {
    private static final Logger log = Logger.getLogger("DBChoice");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // SQL use case: ACID transfer + audit + relational report
        SqlAccountStore sql = new SqlAccountStore();
        sql.open("SAV2001", new BigDecimal("1000000"));
        sql.open("CUR3001", new BigDecimal("250000"));
        sql.transferWithAudit("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info(() -> "SQL report: " + sql.report());

        // NoSQL use case: flexible customer document by key
        NoSqlProfileStore nosql = new NoSqlProfileStore();
        Map<String,Object> doc = new HashMap<>();
        doc.put("name", "Rajesh"); doc.put("tier", "gold");
        doc.put("recentLogins", List.of("2026-11-01T02:00Z", "2026-10-31T21:00Z"));
        nosql.put("SAV2001", doc);
        log.info(() -> "NoSQL profile SAV2001 = " + nosql.get("SAV2001"));

        // Advisor recommends per workload
        DatabaseAdvisor advisor = new DatabaseAdvisor();
        log.info(() -> "ledger: " + advisor.recommend(true, true, false, true));
        log.info(() -> "activity log: " + advisor.recommend(false, false, true, false));
        log.info(() -> "session store: " + advisor.recommend(false, false, true, false));
    }
}

