// ─── File: NoSqlProfileStore.java ───
package com.bank.dbchoice;

import java.util.*;

// Document store: schema-less, denormalized, read by key in one lookup.
public class NoSqlProfileStore {
    private final Map<String, Map<String,Object>> docs = new HashMap<>();
    public void put(String key, Map<String,Object> doc) { docs.put(key, doc); }
    public Map<String,Object> get(String key) { return docs.get(key); }
    // schema can vary per document; no migration needed to add a field
    public void addField(String key, String field, Object value) {
        docs.computeIfAbsent(key, k -> new HashMap<>()).put(field, value);
    }
}
```

