// ─── File: DatabaseAdvisor.java ───
package com.bank.dbchoice;

public class DatabaseAdvisor {
    // recommend based on workload traits
    public String recommend(boolean needsAcid, boolean highlyRelational,
                            boolean needsHorizontalScale, boolean stableSchema) {
        if (needsAcid || highlyRelational) return "SQL (ACID + relations + complex queries)";
        if (needsHorizontalScale && !stableSchema) return "NoSQL (scale + flexible schema + key access)";
        return "SQL by default unless scale/flexibility dominate";
    }
}
